@Service
public class OrderEventProducer {

    private final KafkaTemplate<String, OrderEvent> kafkaTemplate;
    private static final String TOPIC = "order-events";

    public OrderEventProducer(KafkaTemplate<String, OrderEvent> kafkaTemplate) {
        this.kafkaTemplate = kafkaTemplate;
    }

    public void publishOrderCreated(String orderId, OrderPayload payload) {
        OrderEvent event = new OrderEvent("ORDER_CREATED", payload);
        // Using orderId as the key guarantees that all events for this specific order
        // land in the same partition, preserving strict chronological processing order.
        CompletableFuture<SendResult<String, OrderEvent>> future = kafkaTemplate.send(TOPIC, orderId, event);

        future.whenComplete((result, ex) -> {
            if (ex == null) {
                log.info("Published event for order {} to partition {}", orderId, result.getRecordMetadata().partition());
            } else {
                log.error("Failed to publish event for order {}", orderId, ex);
                // Trigger fallback outbox or circuit breaker logic
            }
        });
    }
}
